# prune: keep=3 -> only newest 3 local generations and 3 archive copies
for i in 3 4 5 6; do echo "n$i" > "$d/logs/app.log"; bash bin/rotate "$d/logs" "$d/archive" app.log 2026100$i; done
l=$(ls "$d/logs" | grep -c '^app.log\.[0-9]*$'); [ "$l" = 3 ] || { echo "local count $l"; fail=1; }
[ -e "$d/logs/app.log.4" ] && { echo "app.log.4 left"; fail=1; }
[ "$(cat "$d/logs/app.log.1")" = n6 ] || { echo "newest local"; fail=1; }
a=$(ls "$d/archive" | wc -l); [ "$a" = 3 ] || { echo "archive count $a"; fail=1; }
[ -e "$d/archive/app.log.20261006" ] && [ ! -e "$d/archive/app.log.20261002" ] || { echo "archive newest"; fail=1; }
rm -rf "$d"

